{
  "concepts": [
    {
      "conditions": [],
      "definition": "Runtime role owning traversal, dispatch, actor invocation, process supervision, graph-call realisation, runtime facts, runtime event emission and replay, frames, continuations, retry and correction control, closure folds over runtime truth, re-entry after publish boundaries, lineage and provenance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 591,
          "quote": "ABG owns traversal; dispatch; actor invocation; process supervision;\ngraph-call realisation; runtime facts; runtime event emission and replay;\nframes; continuations; retry and correction control; closure folds over\nruntime truth; re-entry after publish boundaries; lineage and provenance\n(P6).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is%2FABG",
          "start_line": 587
        }
      ],
      "key": "abg",
      "label": "ABG"
    },
    {
      "conditions": [],
      "definition": "Domain product owning domain asset meaning, graph-function meaning, the published function catalogue, policy overlays, domain query projections, and domain closure and gap interpretation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 597,
          "quote": "The ODD product owns domain asset meaning, graph-function meaning, the\npublished function catalogue, policy overlays, domain query projections,\nand closure and gap interpretation for its domain (P6, P1).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is%2FODD%20product",
          "start_line": 595
        }
      ],
      "key": "odd_product",
      "label": "ODD product"
    },
    {
      "conditions": [],
      "definition": "Service and query surfaces whose possible responsibilities are transport, sessions, routing, browser-safe projection and APIs; these responsibilities exclude runtime and continuation truth.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 604,
          "quote": "Service or query layers may own transport, sessions, routing,\nbrowser-safe projection and API surfaces. They own neither runtime truth\nnor continuation truth. The real constructive carrier is never hidden\nbehind the word service (P6).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is%2FQuery%20and%20service%20layers",
          "start_line": 601
        }
      ],
      "key": "service_query_layers",
      "label": "Query and service layers"
    },
    {
      "conditions": [],
      "definition": "Explicit typed domain assets or nodes, with concrete assets explicitly bound into typed domain boundaries and an asset_surface declaration at real produced or consumed boundaries.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 617,
          "quote": "Concrete assets must bind explicitly into\ntyped domain boundaries. Where an asset is a real produced or consumed boundary,\nits `asset_surface` is declared (P3).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.1%20Typed%20assets%20and%20nodes%20are%20explicit",
          "start_line": 615
        }
      ],
      "key": "typed_assets",
      "label": "Typed assets and nodes"
    },
    {
      "conditions": [],
      "definition": "Named GraphFunction or lawful graph-function composition carrying an operative constructive step; its public outer contract is distinguished from inner vectors and implementation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 622,
          "quote": "Every operative constructive step is carried by one named `GraphFunction`\nor one lawful graph-function composition.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.2%20Graph%20functions%20are%20the%20primary%20constructive%20carrier",
          "start_line": 621
        }
      ],
      "key": "graph_function",
      "label": "Graph-function carrier"
    },
    {
      "conditions": [],
      "definition": "Pre-implementation declaration of governed movement: source and target asset types, edge traversal or graph-function name, closure or evaluation obligation, lineage obligation, ambiguity or gap obligation, and allowed F_D, F_P and F_H bindings. Its declarative carrier comprises GTL graph functions, typed nodes, vectors, operator and evaluator bindings, carrier schemas, policy, projection and lineage-ledger declarations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 643,
          "quote": "An outcome traversal declares the governed movement before\nimplementation: source asset type; target asset type; edge traversal or\ngraph-function name; closure or evaluation obligation; lineage obligation;\nambiguity or gap obligation; allowed `F_D`, `F_P` and `F_H` bindings. The\ndeclarative carrier structure is GTL graph functions, typed nodes,\nvectors, operator bindings, evaluator bindings, carrier schemas, policy\ndeclarations, projection declarations and lineage ledger declarations\n(P0, P3).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.2A%20Outcome-first%20realisation%20order",
          "start_line": 636
        }
      ],
      "key": "outcome_traversal",
      "label": "Outcome traversal and declarative carrier"
    },
    {
      "conditions": [],
      "definition": "Machine-readable publication of retained functions, distinct from callable descriptions existing only in prose or prompt memory.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 659,
          "quote": "The live line must publish a machine-readable function catalogue. At\nminimum each retained function should expose its name, inputs, outputs,\nintent, and public or helper role. A callable surface that exists only in\nprose or in prompt memory leaves the product under-built (P6, P3).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.3%20The%20function%20catalogue%20is%20published",
          "start_line": 656
        }
      ],
      "key": "function_catalogue",
      "label": "Function catalogue"
    },
    {
      "conditions": [],
      "definition": "Operative publication surface for public graph-function carriers, their traversed graphs, typed node/vector surfaces, outer callable contracts and explicit refinement boundaries.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 666,
          "quote": "The product must publish the public graph-function carriers, the graph or\ngraphs those carriers traverse, typed node and vector surfaces, and the\nsemantic jobs or equivalent outer callable contracts bound to the public\ncarrier.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.4%20The%20GTL%20module%20is%20the%20operative%20publication%20surface",
          "start_line": 663
        }
      ],
      "key": "gtl_module",
      "label": "GTL module"
    },
    {
      "conditions": [],
      "definition": "Visible current-state and query read models over admitted constructive history, carrier, runtime, event or source truth; their visibility is not replacement runtime authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 679,
          "quote": "Visible current state is a projection and does not replace runtime truth.\nThe ODD query lane may expose asset views, function catalogue views,\ncheckpoint overlays, provenance overlays and domain-specific\nexplainability overlays; it must not redefine ABG runtime facts (P3, P6).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5%20Current%20state%20is%20a%20projection%20over%20constructive%20history",
          "start_line": 676
        }
      ],
      "key": "projection",
      "label": "Projection and query read model"
    },
    {
      "conditions": [
        "An ODD product over GTL/ABG changes one of the listed execution-related surfaces."
      ],
      "definition": "Pre-activation and pre-closure audit of execution ownership, including exactly-one-authority proof, a five-surface inventory and implementation-level evidence ruling out hidden execution authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 708,
          "quote": "An ODD product over GTL/ABG that changes runtime, `start` or `iterate`,\nworker transport, actor invocation, process supervision, plugin dispatch,\nevent projection, closure, assurance, retry or continuation semantics\nmust include an execution-authority audit before activation and closure\n(P6).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5B%20Execution%20authority%20audit",
          "start_line": 704
        }
      ],
      "key": "execution_authority_audit",
      "label": "Execution-authority audit"
    },
    {
      "conditions": [
        "ODD product over GTL/ABG."
      ],
      "definition": "One framework-independent constructive homeostasis loop from intent lineage and model synthesis through observation to lawful next action. It corrects toward required conditions as observations arrive, guarantees neither convergence nor adequacy of those conditions, and distinguishes the four externally defined diagnostic causes.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 796,
          "quote": "Every ODD product over GTL/ABG must preserve one constructive evaluation\nloop running from intent lineage and model synthesis through observation\nto the next lawful action. This is the profile's homeostasis loop, and\nits constitutional surface names the operative functions directly:\n`synthesize_model`, `eval_gap`, `evaluate_next` and `evaluate_action`\n(P2, P5, P6). The loop is this profile's binding of\n[ACTIVATION §1 Feedback and diagnosis](ACTIVATION.md#construction-relation):\nit corrects towards the required conditions as observations arrive,\nguarantees neither convergence nor the adequacy of those conditions, and\nits diagnoses distinguish the four causes named there (P2, P6).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 787
        }
      ],
      "key": "constructive_loop",
      "label": "Constructive evaluation and yield loop"
    },
    {
      "conditions": [],
      "definition": "Loop input and observation domains: IntentLineage is admitted human, imported-source, prior-product, intent-engine or prior-construction-intent lineage backed by ABG event-log truth; ProductAssetModel is product-owned desired/known typed asset truth synthesized from lineage, prior model and admitted product truth, with admitted-event and product-projection publication refs; Worksite is workspace, runtime archive, transform assets, product asset root, profile and observed file/process substrate, not inherent authority; RuntimeEventLog is append-only admitted ABG facts; RuntimeProjection is ABG replay-derived state over event log and execution basis; ObservationSnapshot is a read-only ABG evaluator view of runtime truth and relevant worksite facts with product domain rows; GapPressureRow gives product meaning to missing, partial, blocked, waiting or ambiguous assets/evidence over admitted observation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 846,
          "quote": "| `ObservationSnapshot` | Read-only view of runtime truth plus worksite facts relevant to construction. | ABG evaluator carrier with product domain rows. |\n| `GapPressureRow` | Typed pressure over missing, partial, blocked, waiting, or ambiguous assets and evidence. | Product domain meaning over admitted observation. |",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 845
        }
      ],
      "key": "loop_observation_carriers",
      "label": "Intent, model and observation carriers"
    },
    {
      "conditions": [],
      "definition": "TargetObligationBinding binds gap pressure exactly to selected Product outcome, any admitted prerequisite/experiment basis, target assets, required roles, evidence refs and admissible graph outcomes; it is product domain binding over GTL/ABG action authority. ActionCatalog publishes lawful graph functions, vectors, targets, inputs and eligible outcomes for ABG consumption. PriorityProjection deterministically ranks bound lawful actions under visible product policy using the ABG evaluator kernel. ConstructionIntent is an admitted selection for one bounded graph invocation preserving outcome/bounded-basis refs, under ABG admission and traversal authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 848,
          "quote": "| `TargetObligationBinding` | Exact binding from gap pressure to the selected Product outcome, any admitted prerequisite or experiment basis, target assets, required roles, evidence refs, and admissible graph outcomes. | Product domain binding over GTL/ABG action authority. |\n| `ActionCatalog` | Published lawful graph actions: graph functions, vectors, targets, inputs, and eligible outcomes. | GTL/product publication consumed by ABG. |",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 847
        }
      ],
      "key": "loop_action_carriers",
      "label": "Binding, catalogue, priority and construction intent"
    },
    {
      "conditions": [],
      "definition": "AdmittedEvidence comprises admitted worker, process, product, execution, materialization, liveness and postflight evidence under ABG/product admission, never worker self-closure. EdgeFulfillmentLedger carries closure evidence and convergence for one edge attempt/version. EdgeClosureDecision is the closed sum close, yield, retry, repair, re-enter, reprice, block over that ledger. NextActionBasis distinguishes initial_selection, post_yield_resume, post_close_graph_continuation, post_retry, post_repair, post_reenter, post_reprice and post_block; it is dispatch basis, not another controller, and post_reprice carries no action-selection authority. NextActionProjection is an ABG next-action read model over that basis and current truth with product policy, selecting only when lawful.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 855,
          "quote": "| `EdgeClosureDecision` | Sum type over the ledger: close, yield, retry, repair, re-enter, reprice, block. | Closure decision truth. |\n| `NextActionProjection` | Read model that observes `NextActionBasis` plus current truth and selects a next graph action only when lawful. | ABG next-action evaluation projection with product policy. |",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 854
        }
      ],
      "key": "loop_evidence_decision_carriers",
      "label": "Evidence, ledger, closure and next-action carriers"
    },
    {
      "conditions": [],
      "definition": "Four distinct authority functions: synthesize_model performs model synthesis; eval_gap discovers gaps read-only; evaluate_next selects next actions; evaluate_action evaluates the action just taken. Sharing implementation libraries does not merge their authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 859,
          "quote": "The loop has one model-synthesis function and three distinct evaluation\nfunctions. They may share underlying libraries; they must not share\nauthority (P6):",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 857
        }
      ],
      "key": "evaluation_functions",
      "label": "Model synthesis and evaluation functions"
    },
    {
      "conditions": [],
      "definition": "Subject-defined result distinctions: edge-obligation results from evaluate_action, action-selection no-action results from evaluate_next, candidate-availability step results, and candidate-acceptance dispositions answer different predicates. Closure decisions retain their domain vocabulary alongside exactly one cause-refined core value; they are not ACTIVATION dispositions accept, local_repair, re_enter or reject.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1189,
          "quote": "A closure decision is not a disposition and is never recorded\nas one, and no disposition is a closure decision: `repair` is not\n`local_repair`, and `re-enter` is not `re_enter`. Edge closure is\nevidence toward acceptance and never acceptance itself",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 1186
        }
      ],
      "key": "loop_result_domains",
      "label": "Closure, selection, availability and acceptance result domains"
    },
    {
      "conditions": [],
      "definition": "Conforming agentic development combines an F_P walkthrough establishing that the constitutional process can be followed from minimal declared authority with an F_D artifact-admission gate establishing conformance of each produced act. The coder reasons, drafts and proposes; admission deterministically gates artifacts.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1463,
          "quote": "Conformance has two halves: an F_P proof that the process can be followed,\nand an F_D gate that admits the produced artifacts (P6).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.7A%20Conforming%20agentic%20development",
          "start_line": 1462
        }
      ],
      "key": "agentic_conformance",
      "label": "Agentic walkthrough and deterministic admission"
    },
    {
      "conditions": [],
      "definition": "Graph-native proving surface for a feature/use-case boundary, pre-existing assets, traversed vectors, significant paths and closure evidence; declared scenarios and use cases are described as the best proving-path source because they pressure feature intent and design decisions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1606,
          "quote": "Scenarios are graph-native proving surfaces, not only test\ndocumentation. A scenario bundle should make clear which feature or\nuse-case boundary is exercised; which assets are expected to exist before\nthe scenario starts; which vectors are expected to be traversed; which\nsignificant paths are expected to be exercised; and what evidence closes\nthe scenario (P2, P6).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F12.%20Scenario%20rule",
          "start_line": 1601
        }
      ],
      "key": "scenario",
      "label": "Scenario bundle"
    },
    {
      "conditions": [],
      "definition": "ODD source-defined onboarding procedures: invocation sequence for building with ODD, cold-start reading order for concrete products, and ramp-up questions assessing whether the product is sufficiently ODD-shaped.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1683,
          "quote": "When an agent or designer is told `using ODD, build this product`, the\nexpected sequence is (P2, P0):",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F17.%20Invocation%20rule",
          "start_line": 1682
        }
      ],
      "key": "odd_onboarding",
      "label": "ODD invocation and onboarding"
    },
    {
      "conditions": [],
      "definition": "Derived summary of the same-digest ODD member, sourced from §1, §2, §11.1–§11.5D, §11.7 and §11.7A. It summarizes graph-native authoring, outcome-first construction, ABG authority, evaluation, projection, manual explainability, yield and agentic admission; it owns no determination.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1804,
          "quote": "This section is a compression of this member, a derived surface in the\nsense of [ACTIVATION §2](ACTIVATION.md#2-context-construction-under-an-envelope),\nAcquisition. Its sources are §1, §2, §11.1 to §11.5D, §11.7 and §11.7A of\nthis member at the same digest, and it owns no determination. Where it and\na source section differ, the source section decides",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F20.%20Canonical%20compression",
          "start_line": 1800
        }
      ],
      "key": "odd_canonical_compression",
      "label": "ODD canonical compression"
    },
    {
      "conditions": [],
      "definition": "ODD's provenance account claims receipt and conservation of all 48 rc.2 ODD_METHOD rows under STDO-UP-015, with same modal force, exact formal blocks/tables and rewritten prose. It records successor member names, indicative-law/never restatements of imperatives, labelled rather than bold axiom titles, and British prose spelling with identifiers retained.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1821,
          "quote": "Rows of rc.2 ODD_METHOD.md received by this member, all 48 under\nSTDO-UP-015. Anchors are into rc.2 ODD_METHOD.md; a locus is a section of\nthis file. Every conserved row is restated in this member's own text at\nthe predecessor's modal force; a route is provenance only. Formal content\n(code blocks and tables) is carried exactly and the prose around it is\nrewritten.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/ODD.md#ODD%2F21.%20Source%20dispositions",
          "start_line": 1810
        }
      ],
      "key": "odd_source_dispositions",
      "label": "ODD predecessor disposition account"
    },
    {
      "conditions": [],
      "definition": "Guide owning the governed project's commentary layer: post purpose, authority boundary, location, identity, categories, structure, discussion state, posting rules and ratification. It consumes, without redefining, PRODUCT_DEFINITION §8 comment binding, TICKETS §1 comments, SPEC_METHOD §2 authority surfaces and EVALUATION §1 claims/evidence. Shared-method adoption law belongs to SPEC_METHOD §6. Principle references P0–P6 and rc.2 routes are attribution/provenance, not dependence on that cut.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 11,
          "quote": "Guide. Owns the commentary layer of a governed project: what a post is\nfor, its boundary with authority, where posts live, their identity,\ncategories and structure, their discussion state, the posting rules and\nratification. Consumes\n[PRODUCT_DEFINITION §8](PRODUCT_DEFINITION.md#8-what-how-and-work-carriers)\n(the `ticketing.comments` binding), [TICKETS §1](TICKETS.md#comments)\n(comments among the work carriers), [SPEC_METHOD §2](SPEC_METHOD.md#2-the-chain)\n(the surfaces that carry authority) and [EVALUATION §1](EVALUATION.md#1-claims)\n(claims and evidence); defines none of them.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/POSTING_GUIDE.md#POSTING_GUIDE",
          "start_line": 3
        }
      ],
      "key": "posting_guide",
      "label": "POSTING_GUIDE"
    },
    {
      "conditions": [],
      "definition": "Working commentary for analysis, criticism, proposed changes, handoff or repricing confidence, potentially influencing later specification/design but not itself constitutional truth.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 31,
          "quote": "A post is not constitutional truth. It is working commentary, and it may\nlater influence specification or design (P6).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/POSTING_GUIDE.md#POSTING_GUIDE%2F1.%20Position",
          "start_line": 30
        }
      ],
      "key": "post",
      "label": "Post"
    },
    {
      "conditions": [],
      "definition": "Closed category set: REVIEW critiques code/specification/design/posts; STRATEGY proposes technical or methodological direction; GAP identifies precise insufficiency/contradiction; SCHEMA describes data/event/interface/contract shape; HANDOFF transfers bounded context/task state; MATRIX compares decision options explicitly.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 89,
          "quote": "- `REVIEW`: critique of code, specification, design or another post;\n- `STRATEGY`: a proposed technical or methodological direction;\n- `GAP`: a precise insufficiency or contradiction;\n- `SCHEMA`: the shape of a data model, event model, interface or contract;\n- `HANDOFF`: a bounded transfer of context or task state; and\n- `MATRIX`: an explicit comparison of options for a decision.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76bde1a6b8f1153a25bd6d71c216e/source/standards/POSTING_GUIDE.md#POSTING_GUIDE%2F5.%20Categories",
          "start_line": 84
        }
      ],
      "key": "post_categories",
      "label": "Post categories"
    },
    {
      "conditions": [],
      "definition": "Discussion-state domain: Draft means the author is still shaping the post; Open means publication into active discussion; Closed means the discussion has concluded. Closed commentary is not ratification.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 125,
          "quote": "- `Draft`: the author is still shaping the post;\n- `Open`: the post is published into an active discussion; and\n- `Closed`: the discussion has concluded.",
